final class GesturePreview {
    private(set) var isRunning = true
    func stop() { isRunning = false }
    deinit { print("Превью освобождено") }
}
var preview: GesturePreview? = GesturePreview()
var inspector = preview
preview = nil
inspector!.stop()
print(inspector!.isRunning)
inspector = nil
print("Инспектор закрыт")

Вывод: false, «Превью освобождено», «Инспектор закрыт». stop меняет рабочее состояние живого объекта; освобождение происходит отдельно.

