final class AlarmSoundPicker {
    var onApply: (() -> Void)?
    var selected = "Дождь"
    deinit { print("Выбор звука освобождён") }
    func install() { onApply = { print(self.selected) } }
}
var picker: AlarmSoundPicker? = AlarmSoundPicker()
picker!.install()
picker!.onApply?()
picker!.onApply = nil
picker = nil
print("Выбор закрыт")

Сначала вызван onApply: «Дождь». Очистка onApply разрывает связь объект → замыкание → объект, затем picker = nil приводит к «Выбор звука освобождён». Последняя строка — «Выбор закрыт».
